___CSS_LOADER_EXPORT___.push([module.id, `.md-tree {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.md-tree__toolbar {
  padding: 8px 10px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.10);
}

.md-tree__search {
  width: 100%;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  padding: 6px 8px;
  background: rgba(0, 0, 0, 0.25);
  color: rgba(255, 255, 255, 0.85);
  font-size: 12px;
}

.md-tree__content {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 6px 0;
}

.md-tree__node {
  user-select: none;
}

.md-tree__row {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 22px;
}

.md-tree__toggle {
  width: 18px;
  height: 18px;
  border: none;
  background: transparent;
  color: rgba(255, 255, 255, 0.75);
  cursor: pointer;
}

.md-tree__toggle:hover {
  color: rgba(255, 255, 255, 0.95);
}

.md-tree__spacer {
  display: inline-block;
  width: 18px;
  height: 18px;
}

.md-tree__label {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.85);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.md-tree__label.is-draggable {
  cursor: grab;
}

.md-tree__label.is-draggable:active {
  cursor: grabbing;
}

.md-tree__hint {
  padding: 8px 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.10);
  font-size: 11px;
  color: rgba(255, 255, 255, 0.6);
}
