 * Модальное окно параметров виртуальной таблицы (редактор СКД).
 * Высота контролов фиксирована, чтобы подписи, поле «Условие» и «…» совпадали по вертикали.
 */

.vt-modal__overlay {
  position: fixed;
  inset: 0;
  z-index: 10000;
  background: rgba(0, 0, 0, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
}

.vt-modal {
  width: min(520px, calc(100vw - 48px));
  background: #1e1e1e;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 10px;
  overflow: hidden;
}

.vt-modal *,
.vt-modal *::before,
.vt-modal *::after {
  box-sizing: border-box;
}

.vt-modal__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

.vt-modal__title {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.3;
}

.vt-modal__close {
  border: none;
  background: transparent;
  color: rgba(255, 255, 255, 0.8);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  line-height: 1;
  flex-shrink: 0;
}

.vt-modal__body {
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.vt-modal__row {
  display: grid;
  grid-template-columns: 150px 1fr;
  gap: 10px;
  align-items: center;
}

.vt-modal__label {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.8);
  display: flex;
  align-items: center;
  height: 26px;
  line-height: 1;
}

.vt-modal__field {
  min-width: 0;
  display: flex;
  align-items: center;
  width: 100%;
}

.vt-modal__input {
  width: 100%;
  height: 26px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  padding: 0 8px;
  margin: 0;
  background: rgba(0, 0, 0, 0.25);
  color: rgba(255, 255, 255, 0.9);
  font-size: 12px;
  line-height: 1;
}

select.vt-modal__input {
  appearance: auto;
}

.vt-modal__condition {
  display: flex;
  flex-direction: row;
  flex-wrap: nowrap;
  align-items: center;
  width: 100%;
  gap: 8px;
}

.vt-modal__condition .vt-modal__input {
  flex: 1 1 auto;
  width: auto;
  min-width: 0;
}

.vt-modal__btn {
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 6px;
  padding: 0 12px;
  margin: 0;
  min-height: 26px;
  background: transparent;
  color: rgba(255, 255, 255, 0.85);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  font-size: 12px;
}

.vt-modal__btn--ellipsis {
  flex: 0 0 26px;
  width: 26px;
  height: 26px;
  min-height: 26px;
  padding: 0;
}

.vt-modal__btn--primary {
  background: #0e639c;
  border-color: rgba(14, 99, 156, 0.8);
  color: white;
}

.vt-modal__footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  padding: 10px 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
}
