}

.dcs-metadata-tree-loading {
  padding: 10px 12px;
  font-size: 12px;
  opacity: 0.7;
}

.dcs-detailsRoot {
  padding: 10px 12px;
}

.dcs-details__head {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  margin-bottom: 10px;
}

.dcs-details__name {
  font-size: 13px;
