  max-height: 300px;
  overflow: auto;
  transition: border-color 0.15s, background-color 0.15s;
}

.dcs-query-preview:hover {
  border-color: var(--vscode-focusBorder);
  background-color: var(--vscode-list-hoverBackground);
}

.dcs-query__textarea {
