.edt-header__title {
  display: flex;
  align-items: baseline;
  gap: 10px;
}

.edt-header__name-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.edt-header__name {
  font-size: 16px;
  font-weight: 600;
}

.edt-header__props-btn {
  padding: 4px 10px;
  font-size: 12px;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  background: var(--vscode-button-secondaryBackground);
  color: var(--vscode-button-secondaryForeground);
  cursor: pointer;
}

.edt-header__props-btn:hover {
  background: var(--vscode-button-secondaryHoverBackground);
}

.edt-header__meta {
  font-size: 12px;
  color: var(--vscode-descriptionForeground);
}

.edt-header__path {
  font-size: 11px;
  color: var(--vscode-descriptionForeground);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.edt-layout {
  display: flex;
  flex-direction: row;
  height: 100%;
  min-height: 0;
}

.edt-layout__main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.edt-top {
  display: flex;
  flex: 1;
  min-height: 220px;
  border-bottom: 1px solid var(--vscode-panel-border);
}

/* Разделители для изменения размеров панелей */
.edt-resizer {
  flex-shrink: 0;
  background: var(--vscode-panel-border);
  z-index: 1;
}
.edt-resizer--vertical {
  width: 6px;
  min-width: 6px;
  cursor: col-resize;
}
.edt-resizer--vertical:hover {
  background: var(--vscode-focusBorder);
}
.edt-resizer--horizontal {
  height: 6px;
  min-height: 6px;
  cursor: row-resize;
  flex-shrink: 0;
}
.edt-resizer--horizontal:hover {
  background: var(--vscode-focusBorder);
}
body.edt-resizing {
  user-select: none;
  cursor: inherit;
}
body.edt-resizing .edt-resizer--vertical {
  cursor: col-resize;
}
body.edt-resizing .edt-resizer--horizontal {
  cursor: row-resize;
}

.edt-pane {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
  background: var(--vscode-editor-background);
}

.edt-pane--left {
  border-right: 1px solid var(--vscode-panel-border);
}

/* Панель «Свойства»: в режиме overlay перекрывает панель «Дизайнер» справа */
.edt-properties-panel {
  display: flex;
  flex-direction: column;
  min-height: 0;
  min-width: 0;
  background: var(--vscode-editor-background);
  border-left: 1px solid var(--vscode-panel-border);
}


.edt-properties-panel__wrap {
  display: flex;
  flex-direction: column;
  min-height: 0;
  height: 100%;
}

.edt-properties-panel__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 10px;
  border-bottom: 1px solid var(--vscode-panel-border);
  flex-shrink: 0;
}

.edt-properties-panel__title {
  font-size: 12px;
  font-weight: 600;
  color: var(--vscode-foreground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.edt-properties-panel__close {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  background: var(--vscode-button-secondaryBackground);
  color: var(--vscode-button-secondaryForeground);
  font-size: 16px;
  line-height: 1;
  cursor: pointer;
}

.edt-properties-panel__close:hover {
  background: var(--vscode-button-secondaryHoverBackground);
}

.edt-properties-panel__search {
  padding: 6px 8px;
  border-bottom: 1px solid var(--vscode-panel-border);
  flex-shrink: 0;
}

.edt-properties-panel__search .edt-search {
  width: 100%;
}

.edt-properties-panel__body {
  flex: 1;
  min-height: 0;
  overflow: hidden;
  padding: 6px 8px;
  display: flex;
  flex-direction: column;
}

.edt-properties-panel__section-area {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.edt-properties-panel__section-area--events {
  flex: 1 1 0;
}

.edt-properties-panel__resizer {
  flex-shrink: 0;
  height: 8px;
  min-height: 8px;
  cursor: row-resize;
  background: var(--vscode-panel-border);
  margin: 4px 0;
  border-radius: 2px;
  user-select: none;
}

.edt-properties-panel__resizer:hover {
  background: var(--vscode-focusBorder);
}

body.edt-resizing-props-sections {
  user-select: none;
  cursor: row-resize;
}

.edt-properties-panel__section-content--scrollable {
  overflow-y: auto;
  overflow-x: hidden;
  flex: 1 1 0;
  min-height: 0;
  min-height: 120px;
  max-height: 50vh;
}

.edt-properties-panel__section {
  margin-bottom: 8px;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
}

.edt-properties-panel__section-title {
  padding: 6px 8px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  list-style: none;
  background: var(--vscode-editor-inactiveSelectionBackground);
}

.edt-properties-panel__section-title::-webkit-details-marker {
  display: none;
}

.edt-properties-panel__section-content {
  padding: 6px 8px;
}

.edt-properties-panel__section-content--scroll {
  flex: 1 1 0;
  min-height: 0;
  overflow-y: auto;
  overflow-x: hidden;
}

.edt-properties-panel__section--events .edt-properties-panel__section-content--scroll {
  min-height: 120px;
  max-height: 50vh;
}

.edt-properties-panel__events {
  list-style: none;
  margin: 0;
  padding: 0;
}

.edt-properties-panel__event-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 0;
  font-size: 12px;
}

.edt-properties-panel__event-name {
  flex-shrink: 1;
  min-width: 0;
  max-width: 45%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--vscode-foreground);
}

.edt-properties-panel__event-handler {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 4px;
}

.edt-properties-panel__event-input {
  flex: 1;
  min-width: 0;
  box-sizing: border-box;
  padding: 4px 6px;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  background: var(--vscode-input-background);
  color: var(--vscode-input-foreground);
  font-size: 12px;
}

.edt-properties-panel__event-input[readonly] {
  opacity: 0.9;
  cursor: help;
}

.edt-properties-panel__event-open {
  flex-shrink: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  background: var(--vscode-button-secondaryBackground);
  color: var(--vscode-button-secondaryForeground);
  cursor: pointer;
}

.edt-properties-panel__event-open:hover {
  background: var(--vscode-button-secondaryHoverBackground);
}

.edt-properties-panel__event-open img {
  display: block;
  pointer-events: none;
}

.edt-pane__body {
  min-height: 0;
  overflow: auto;
}

.edt-tabs {
  display: flex;
  gap: 4px;
  padding: 6px 8px;
  border-bottom: 1px solid var(--vscode-panel-border);
}

.edt-tab {
  padding: 6px 10px;
  font-size: 12px;
  border: 1px solid var(--vscode-panel-border);
  background: var(--vscode-button-secondaryBackground);
  color: var(--vscode-button-secondaryForeground);
  border-radius: 3px 3px 0 0;
  cursor: pointer;
}

.edt-tab.is-active {
  background: var(--vscode-editor-background);
  color: var(--vscode-foreground);
  border-bottom-color: var(--vscode-editor-background);
}

.edt-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border-bottom: 1px solid var(--vscode-panel-border);
}

.edt-toolbar--icons {
  justify-content: flex-start;
}

.edt-icon-btn {
  width: 26px;
  height: 26px;
  border-radius: 3px;
  border: 1px solid var(--vscode-panel-border);
  background: var(--vscode-button-secondaryBackground);
  color: var(--vscode-button-secondaryForeground);
  cursor: pointer;
  font-size: 14px;
  line-height: 1;
}

.edt-icon-btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.edt-search {
  width: 100%;
  padding: 6px 10px;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 4px;
  background: var(--vscode-input-background);
  color: var(--vscode-input-foreground);
}

.edt-search:focus {
  outline: none;
  border-color: var(--vscode-focusBorder);
}

.edt-grid {
  padding: 6px 8px;
}

.edt-grid__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.edt-grid__table th,
.edt-grid__table td {
  border: 1px solid var(--vscode-panel-border);
  padding: 6px 8px;
  vertical-align: top;
}

.edt-grid__table thead th {
  position: sticky;
  top: 0;
  background: var(--vscode-editor-background);
  z-index: 1;
  font-weight: 600;
}

.edt-grid__table tbody tr.is-selected td {
  background: var(--vscode-list-activeSelectionBackground);
  color: var(--vscode-list-activeSelectionForeground);
}

.edt-grid__table tbody tr.is-subrow td {
  color: var(--vscode-descriptionForeground);
}

.edt-grid__table tbody tr:hover td {
  background: var(--vscode-list-hoverBackground);
}

.edt-grid__cell--main {
  font-weight: 600;
}

.attr-tree-cell {
  display: flex;
  align-items: center;
  gap: 6px;
}

.attr-tree-cell.depth-1 {
  padding-left: 16px;
}

.attr-tree-cell.depth-2 {
  padding-left: 32px;
}

.attr-tree-cell__toggle {
  width: 18px;
  height: 18px;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  background: var(--vscode-button-secondaryBackground);
  color: var(--vscode-foreground);
  font-size: 12px;
  line-height: 1;
  cursor: pointer;
  padding: 0;
}

.attr-tree-cell__toggle:hover {
  background: var(--vscode-button-secondaryHoverBackground);
}

.attr-tree-cell__spacer {
  width: 18px;
  height: 18px;
  display: inline-block;
}

.attr-columns-grid {
  margin-top: 6px;
}

.attr-columns__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.attr-columns__actions {
  display: flex;
  gap: 8px;
}

.attr-columns__actionsCell {
  text-align: right;
  white-space: nowrap;
}

.attr-columns__actionsCell .edt-icon-btn {
  margin-left: 4px;
}

.edt-grid__cell--mono {
  font-family: var(--vscode-editor-font-family);
}

/* ===== Properties editor (Form element) ===== */
.edt-props-editor__select {
  width: 100%;
  min-height: 26px;
  padding: 2px 8px;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  background: var(--vscode-dropdown-background, var(--vscode-input-background));
  color: var(--vscode-dropdown-foreground, var(--vscode-input-foreground));
  font-family: var(--vscode-font-family);
  font-size: 12px;
  box-sizing: border-box;
}

.edt-props-editor__select.is-error {
  border-color: var(--vscode-inputValidation-errorBorder, #f14c4c);
}

.edt-props-editor__input {
  width: 100%;
  box-sizing: border-box;
  padding: 4px 6px;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  background: var(--vscode-input-background);
  color: var(--vscode-input-foreground);
  font-size: 12px;
}

.edt-props-editor__textarea {
  width: 100%;
  box-sizing: border-box;
  min-height: 72px;
  padding: 6px 8px;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  background: var(--vscode-input-background);
  color: var(--vscode-input-foreground);
  font-family: var(--vscode-editor-font-family);
  font-size: 12px;
  resize: vertical;
}

.edt-props-editor__input.is-error,
.edt-props-editor__textarea.is-error {
  border-color: var(--vscode-errorForeground);
}

.edt-props-editor__error {
  margin-top: 4px;
  font-size: 11px;
  color: var(--vscode-errorForeground);
}

.edt-props-editor__bool {
  display: inline-flex;
  gap: 8px;
  align-items: center;
  font-size: 12px;
}

.edt-props-editor__table {
  width: 100%;
}

/* Колонка «Свойство»: обрезка длинных имён, без наезжания на «Значение» */
.edt-props-editor__cell-property {
  max-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.edt-props-editor__resizer-cell {
  width: 10px;
  min-width: 10px;
  padding: 0;
  vertical-align: middle;
  border-left: none;
  border-right: none;
  background: var(--vscode-editor-background);
  position: relative;
}

.edt-props-editor__resizer {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  width: 10px;
  min-height: 24px;
  margin: 0 auto;
  cursor: col-resize;
  background: var(--vscode-panel-border);
  border-radius: 1px;
  user-select: none;
}

.edt-props-editor__resizer:hover,
.edt-props-editor__resizer:active {
  background: var(--vscode-focusBorder);
}

body.edt-resizing-props-cols {
  cursor: col-resize;
}

.edt-bottom {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.edt-bottom__title {
  padding: 8px 12px;
  font-size: 12px;
  font-weight: 600;
  color: var(--vscode-descriptionForeground);
  border-bottom: 1px solid var(--vscode-panel-border);
}

.edt-bottom__canvas {
  padding: 10px 12px;
  min-height: 0;
  overflow: auto;
  background: var(--vscode-editor-background);
}

.edt-bottom__hint {
  font-size: 12px;
  color: var(--vscode-descriptionForeground);
  margin-bottom: 8px;
}

.designer {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.designer-node {
  border: 1px solid var(--vscode-panel-border);
  border-radius: 4px;
  background: var(--vscode-editor-background);
  padding: 8px 10px;
  cursor: pointer;
}

.designer-node:hover {
  background: var(--vscode-list-hoverBackground);
}

.designer-node.is-selected {
  outline: 1px solid var(--vscode-focusBorder);
  background: var(--vscode-list-activeSelectionBackground);
  color: var(--vscode-list-activeSelectionForeground);
}

.designer-group__content.is-selected,
.designer-node__children--pages.is-selected,
.designer-table__addition.is-selected {
  outline: 1px solid var(--vscode-focusBorder);
  outline-offset: 1px;
}

.designer-button.is-selected,
.designer-popup__item.is-selected,
.designer-popup__trigger.is-selected {
  outline: 1px solid var(--vscode-focusBorder);
  outline-offset: 1px;
}

.designer-node__title {
  display: flex;
  gap: 8px;
  align-items: baseline;
  font-size: 12px;
  font-weight: 600;
}

.designer-node__type {
  color: var(--vscode-descriptionForeground);
}

.designer-node.is-selected .designer-node__type {
  color: var(--vscode-list-activeSelectionForeground);
}

.designer-node__name {
  font-weight: 500;
}

.designer-node__children {
  margin-top: 8px;
  padding-left: 10px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.designer-node__props {
  margin-top: 6px;
  font-size: 12px;
  color: var(--vscode-descriptionForeground);
}

.designer-node.is-selected .designer-node__props {
  color: var(--vscode-list-activeSelectionForeground);
}

.designer-node__datapath {
  font-family: var(--vscode-editor-font-family);
}

/* ===== Designer: closer to EDT layout ===== */

.designer-edt {
  gap: 10px;
}

.designer-node--pages .designer-node__children--pages {
  margin-top: 8px;
  padding-left: 0;
}

/* PagesRepresentation=None: колонка переноса между списками (>, <<, <) */
.designer-node--pages-notabs {
  display: flex;
  flex-direction: column;
  padding: 2px 0;
  border: none;
  background: transparent;
  min-height: 0;
}

.designer-node--pages-notabs .designer-node__children--pages {
  flex: 1 1 auto;
  margin-top: 0;
  padding-left: 0;
  gap: 4px;
  min-height: 0;
  height: 100%;
  align-items: stretch;
}

.designer-node--spacer {
  border: none;
  padding: 0;
  background: transparent;
  min-width: 0;
  border-radius: 0;
}

.designer-node--spacer-grow {
  flex: 1 1 auto;
  min-height: 8px;
}

.designer-node--spacer-gap {
  flex: 0 0 8px;
  height: 8px;
}

.designer-node--pages-notabs .designer-node--button {
  flex: 0 0 auto;
  padding: 0;
  border: none;
  background: transparent;
  display: flex;
  justify-content: center;
}

.designer-node--pages-notabs .designer-button {
  max-width: none;
  min-width: 28px;
  padding: 0 6px;
}

.designer-tabs {
  display: flex;
  gap: 6px;
  padding: 6px 0 8px;
  overflow: auto;
}

.designer-tab {
  padding: 4px 10px;
  font-size: 12px;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  background: var(--vscode-button-secondaryBackground);
  color: var(--vscode-button-secondaryForeground);
  cursor: pointer;
  white-space: nowrap;
}

.designer-tab.is-active {
  background: var(--vscode-button-background);
  color: var(--vscode-button-foreground);
  border-color: var(--vscode-button-background);
}

.designer-group__content {
  margin-top: 8px;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.designer-group__content--vertical {
  flex-direction: column;
  flex-wrap: nowrap;
}

.designer-group__content--horizontalAlways {
  flex-direction: row;
  flex-wrap: nowrap;
  overflow-x: auto;
  align-items: stretch;
}

.designer-group__content--horizontalAlways > .designer-node {
  /* Колонки: дети делят ширину контейнера (как в EDT), порядок — как в XML */
  flex: 1 1 0;
  min-width: 0;
}

/* ShowTitle=false: группа — сам flex-контейнер, без .designer-node */
.designer-group__content--horizontalAlways > .designer-group__content {
  flex: 1 1 0;
  min-width: 0;
  min-height: 0;
}

.designer-group__content--horizontalAlways > .designer-node--commandbar {
  flex: 0 0 auto;
  align-self: center;
  padding: 0;
  border: none;
  background: transparent;
}

.designer-group__content--horizontalAlways > .designer-node--field-notitle {
  flex: 1 1 auto;
  min-width: 160px;
  padding: 0;
  border: none;
  background: transparent;
}

.designer-popup {
  position: relative;
  flex-shrink: 0;
}

.designer-popup__trigger--picture {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-width: 32px;
  padding: 0 4px;
}

.designer-popup__icon {
  width: 12px;
  height: 12px;
  border: 2px solid currentColor;
  border-radius: 50%;
  position: relative;
  display: inline-block;
  box-sizing: border-box;
}

.designer-popup__icon::after {
  content: '';
  position: absolute;
  width: 6px;
  height: 2px;
  background: currentColor;
  right: -5px;
  bottom: -1px;
  transform: rotate(45deg);
}

.designer-popup__caret {
  font-size: 9px;
  line-height: 1;
  opacity: 0.85;
}

.designer-popup__menu {
  position: absolute;
  top: calc(100% + 2px);
  right: 0;
  z-index: 30;
  min-width: 240px;
  max-width: 360px;
  padding: 4px 0;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  background: var(--vscode-menu-background, var(--vscode-editor-background));
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.28);
}

.designer-popup__item {
  display: block;
  width: 100%;
  text-align: left;
  border: none;
  background: transparent;
  color: var(--vscode-foreground);
  font-size: 12px;
  padding: 5px 12px;
  cursor: pointer;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.designer-popup__item:hover {
  background: var(--vscode-list-hoverBackground);
}

.designer-group__content--horizontalIfPossible {
  flex-direction: row;
  flex-wrap: wrap;
}

.designer-group__content--horizontalIfPossible > .designer-node {
  /* Мягкая сетка: если места хватает — рядом, иначе перенос */
  flex: 1 1 320px;
  min-width: 280px;
}

.designer-node--layout-hidden {
  opacity: 0.55;
  outline: 1px dashed var(--vscode-panel-border);
  outline-offset: 2px;
  border-radius: 4px;
}

.designer-field {
  display: grid;
  grid-template-columns: minmax(120px, 32%) 1fr;
  gap: 8px;
  align-items: center;
}

.designer-field--title-left {
  grid-template-columns: minmax(120px, 32%) 1fr;
}

.designer-field--title-top {
  grid-template-columns: 1fr;
  grid-template-rows: auto auto;
  align-items: start;
}

.designer-field--title-top .designer-field__label {
  white-space: normal;
}

.designer-field--title-none {
  grid-template-columns: 1fr;
}

.designer-field--title-none .designer-field__label {
  display: none;
}

.designer-field--readonly .designer-field__control {
  background: var(--vscode-input-background, rgba(127, 127, 127, 0.12));
  opacity: 0.85;
  cursor: not-allowed;
}

.designer-checkbox--readonly {
  opacity: 0.75;
  cursor: not-allowed;
}

.designer-node--table-readonly .designer-table {
  opacity: 0.9;
}

.designer-field__label {
  font-size: 12px;
  color: var(--vscode-foreground);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.designer-field__control {
  height: 26px;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  background: var(--vscode-input-background);
  color: var(--vscode-input-foreground);
  display: flex;
  align-items: center;
  padding: 0 8px;
}

.designer-field__control.is-multiline {
  height: 44px;
  align-items: flex-start;
  padding-top: 6px;
}

.designer-field__hint {
  font-family: var(--vscode-editor-font-family);
  font-size: 11px;
  color: var(--vscode-descriptionForeground);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  width: 100%;
}

.designer-checkbox {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  color: var(--vscode-foreground);
}

.designer-checkbox__input {
  flex-shrink: 0;
  width: 16px;
  height: 16px;
  margin: 0;
  cursor: default;
  accent-color: var(--vscode-checkbox-foreground, var(--vscode-foreground));
}

.designer-checkbox__label {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

.designer-label {
  font-size: 12px;
  color: var(--vscode-foreground);
}

.designer-picture-decoration {
  display: block;
  object-fit: contain;
}

.designer-commandbar {
  display: flex;
  gap: 4px;
  flex-wrap: nowrap;
  overflow: visible;
  padding: 0;
  align-items: center;
}

.designer-commandbar__empty {
  font-size: 12px;
  color: var(--vscode-descriptionForeground);
}

.designer-button {
  height: 22px;
  padding: 0 8px;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 2px;
  background: var(--vscode-button-secondaryBackground);
  color: var(--vscode-button-secondaryForeground);
  cursor: pointer;
  font-size: 12px;
  white-space: nowrap;
  max-width: 200px;
  overflow: hidden;
  text-overflow: ellipsis;
  flex-shrink: 0;
}

.designer-group__caption {
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 4px;
  color: var(--vscode-foreground);
}

.designer-button:hover {
  background: var(--vscode-button-secondaryHoverBackground);
}

.designer-table__title {
  font-size: 12px;
  font-weight: 600;
  margin-bottom: 6px;
}

.designer-table__additions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 6px;
}

.designer-table__addition {
  flex: 1 1 120px;
  min-height: 22px;
  padding: 2px 8px;
  border: 1px dashed var(--vscode-panel-border);
  border-radius: 3px;
  font-size: 11px;
  color: var(--vscode-descriptionForeground);
  background: var(--vscode-editor-background);
  display: flex;
  align-items: center;
}

.designer-table__bars {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-bottom: 6px;
}

.designer-table__bar {
  min-height: 24px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 2px 8px;
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  background: var(--vscode-editor-background);
  color: var(--vscode-descriptionForeground);
  font-size: 12px;
  white-space: nowrap;
}

.designer-table__barTitle {
  font-weight: 600;
}

.designer-table__barButtons {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.designer-table__barEmpty {
  font-size: 12px;
  color: var(--vscode-descriptionForeground);
}

.designer-table {
  border: 1px solid var(--vscode-panel-border);
  border-radius: 3px;
  overflow: hidden;
}

.designer-table__headGrid {
  display: grid;
  grid-template-columns: var(--designer-table-cols, repeat(3, 1fr));
  grid-auto-rows: 28px;
}

.designer-table__row {
  display: grid;
  grid-template-columns: var(--designer-table-cols, repeat(3, 1fr));
}

.designer-table__cell {
  border-right: 1px solid var(--vscode-panel-border);
  border-bottom: 1px solid var(--vscode-panel-border);
  padding: 6px 8px;
  font-size: 12px;
  color: var(--vscode-foreground);
}

.designer-table__cell:last-child {
  border-right: none;
}

.designer-table__cell--head {
  background: var(--vscode-editor-background);
  color: var(--vscode-descriptionForeground);
  font-weight: 600;
}

.designer-table__cell--group {
  background: var(--vscode-editor-background);
  color: var(--vscode-descriptionForeground);
  font-weight: 600;
  text-align: center;
}

.designer-table__cell--spacer {
  background: var(--vscode-editor-background);
  color: transparent;
}

.designer-table--no-h-lines .designer-table__cell,
.designer-table--no-h-lines .designer-table__headGrid > .designer-table__cell {
  border-bottom: none !important;
}

.designer-table--no-v-lines .designer-table__cell,
.designer-table--no-v-lines .designer-table__headGrid > .designer-table__cell {
  border-right: none !important;
}

.designer-table--no-v-lines .designer-table__cell:last-child,
.designer-table--no-v-lines .designer-table__headGrid > .designer-table__cell:last-child {
  border-right: none !important;
}



/* Monaco suggest-widget: иногда в webview в подсказках видны только иконки без текста.
   Monaco может рендерить suggest-widget вне контейнера модалки, поэтому селектор должен быть максимально широким. */
.monaco-editor .suggest-widget .monaco-icon-label .label-name,
.monaco-editor .suggest-widget .monaco-icon-label .label-description,
.monaco-editor .suggest-widget .monaco-icon-label .monaco-highlighted-label,
.suggest-widget .monaco-icon-label .label-name,
.suggest-widget .monaco-icon-label .label-description,
.suggest-widget .monaco-icon-label .monaco-highlighted-label {
  color: var(--vscode-editorSuggestWidget-foreground, rgba(255, 255, 255, 0.92)) !important;
  -webkit-text-fill-color: currentColor !important;
  opacity: 1 !important;
  visibility: visible !important;
  font-size: 12px !important;
}

/* Иногда текст прячется из-за layout/width — принудим display. */
.monaco-editor .suggest-widget .monaco-icon-label .label-name,
.suggest-widget .monaco-icon-label .label-name {
  display: inline-block !important;
}

.monaco-editor .suggest-widget,
.monaco-editor .suggest-widget,
.suggest-widget {
  background: var(--vscode-editorSuggestWidget-background, #252526) !important;
}

/* максимально широкий фикс: если label-* классы в конкретной версии Monaco отличаются,
   всё равно принудим цвет текста внутри виджета */
.suggest-widget,
.suggest-widget * {
  color: var(--vscode-editorSuggestWidget-foreground, rgba(255, 255, 255, 0.92)) !important;
  -webkit-text-fill-color: currentColor !important;
}

.monaco-editor .suggest-widget .monaco-list-row.focused .monaco-icon-label .label-name,
.monaco-editor .suggest-widget .monaco-list-row:hover .monaco-icon-label .label-name,
.suggest-widget .monaco-list-row.focused .monaco-icon-label .label-name,
.suggest-widget .monaco-list-row:hover .monaco-icon-label .label-name {
  color: var(--vscode-editorSuggestWidget-foreground, rgba(255, 255, 255, 0.98)) !important;
}
.monaco-editor .suggest-widget .monaco-list-row.focused .monaco-icon-label .label-name,
.monaco-editor .suggest-widget .monaco-list-row:hover .monaco-icon-label .label-name {
  color: var(--vscode-editorSuggestWidget-foreground, rgba(255, 255, 255, 0.98)) !important;
}


/* Fix: в некоторых сборках Monaco в webview текст подсказок есть в DOM, но не рисуется.
   Принудительно задаём типографику и раскладку для строк списка. */
.suggest-widget .monaco-list-row,
.monaco-editor .suggest-widget .monaco-list-row {
  font-size: 12px !important;
  line-height: 18px !important;
  color: var(--vscode-editorSuggestWidget-foreground, rgba(255, 255, 255, 0.92)) !important;
  -webkit-text-fill-color: currentColor !important;
}

.suggest-widget .monaco-list-row * ,
.monaco-editor .suggest-widget .monaco-list-row * {
  font-size: 12px !important;
  line-height: 18px !important;
  color: inherit !important;
  -webkit-text-fill-color: currentColor !important;
  opacity: 1 !important;
  visibility: visible !important;
}

/* У некоторых тем/плагинов label рисуется через .monaco-icon-label без label-name/label-description */
.suggest-widget .monaco-icon-label,
.monaco-editor .suggest-widget .monaco-icon-label {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
}

.suggest-widget .monaco-icon-label .monaco-highlighted-label,
.monaco-editor .suggest-widget .monaco-icon-label .monaco-highlighted-label {
  display: inline !important;
  white-space: nowrap !important;
}
