er;\r\n  vertical-align: middle;\r\n  order: -1; /* Гарантируем, что чекбокс всегда слева */\r\n}\r\n\r\n.type-editor-modal .type-item span {\r\n  flex: 1;\r\n  font-size: 13px;\r\n  color: var(--vscode-foreground);\r\n  line-height: 1.4;\r\n}\r\n\r\n/* Заголовки категорий в редакторе типов */\r\n.type-editor-modal .type-category-header label {\r\n  display: flex !important;\r\n  flex-direction: row;\r\n  align-items: center;\r\n  gap: 8px;\r\n  font-weight: 600;\r\n  font-size: 14px;\r\n  color: var(--vscode-foreground);\r\n  cursor: pointer;\r\n}\r\n\r\n.type-editor-modal .type-category-header input[type=\"checkbox\"] {\r\n  margin: 0;\r\n  cursor: pointer;\r\n  flex-shrink: 0;\r\n  align-self: center;\r\n  vertical-align: middle;\r\n}\r\n\r\n/* Единообразие для групп ссылочных типов */\r\n.type-editor-modal .type-group-items {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 4px;\r\n  margin-left: 18px;\r\n  margin-top: 4px;\r\n}\r\n\r\n/**\r\n * ===========================\r\n * Form Preview (EDT-like MVP)\r\n * ===========================\r\n */\r\n\r\n.form-preview {\r\n  display: flex;\r\n  flex-direction: column;\r\n  height: 100vh;\r\n  width: 100%;\r\n  font-family: var(--vscode-font-family);\r\n  color: var(--vscode-foreground);\r\n  background-color: var(--vscode-editor-background);\r\n}\r\n\r\n.form-preview__header {\r\n  padding: 10px 16px;\r\n  border-bottom: 1px solid var(--vscode-panel-border);\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 6px;\r\n}\r\n\r\n.form-preview__title {\r\n  display: flex;\r\n  align-items: baseline;\r\n  gap: 10px;\r\n}\r\n\r\n.form-preview__name {\r\n  font-size: 16px;\r\n  font-weight: 600;\r\n}\r\n\r\n.form-preview__type {\r\n  font-size: 12px;\r\n  color: var(--vscode-descriptionForeground);\r\n}\r\n\r\n.form-preview__path {\r\n  font-size: 11px;\r\n  color: var(--vscode-descriptionForeground);\r\n  white-space: nowrap;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n}\r\n\r\n.form-previe