height: 0;\r\n  overflow: hidden;\r\n}\r\n\r\n/* Левая панель — дерево объектов */\r\n.role-objects-panel {\r\n  width: 300px;\r\n  min-width: 180px;\r\n  max-width: 500px;\r\n  display: flex;\r\n  flex-direction: column;\r\n  border-right: 1px solid var(--vscode-panel-border);\r\n  overflow: hidden;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.role-objects-panel-header {\r\n  padding: 6px 10px;\r\n  font-size: 11px;\r\n  font-weight: 600;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.05em;\r\n  color: var(--vscode-sideBarTitle-foreground);\r\n  background-color: var(--vscode-sideBar-background);\r\n  border-bottom: 1px solid var(--vscode-panel-border);\r\n  flex-shrink: 0;\r\n}\r\n\r\n.role-objects-search {\r\n  padding: 6px 8px;\r\n  border-bottom: 1px solid var(--vscode-panel-border);\r\n  flex-shrink: 0;\r\n}\r\n\r\n.role-objects-search input {\r\n  width: 100%;\r\n  box-sizing: border-box;\r\n  padding: 4px 8px;\r\n  background-color: var(--vscode-input-background);\r\n  color: var(--vscode-input-foreground);\r\n  border: 1px solid var(--vscode-input-border);\r\n  border-radius: 2px;\r\n  font-size: 12px;\r\n  outline: none;\r\n}\r\n\r\n.role-objects-search input:focus {\r\n  border-color: var(--vscode-focusBorder);\r\n}\r\n\r\n.role-objects-tree {\r\n  flex: 1;\r\n  overflow-y: auto;\r\n  overflow-x: hidden;\r\n}\r\n\r\n/* Группа типов объектов */\r\n.role-object-group {\r\n  user-select: none;\r\n}\r\n\r\n.role-object-group-header {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 4px;\r\n  padding: 3px 8px;\r\n  font-size: 12px;\r\n  font-weight: 600;\r\n  color: var(--vscode-sideBarSectionHeader-foreground);\r\n  background-color: var(--vscode-sideBar-background);\r\n  cursor: pointer;\r\n  border-bottom: 1px solid var(--vscode-panel-border);\r\n}\r\n\r\n.role-object-group-header:hover {\r\n  background-color: var(--vscode-list-hoverBackground);\r\n}\r\n\r\n.role-object-group-icon {\r\n  font-size: 10px;\r\n  width: 12px;\r\n  text-align: center;\r\n  color: var(--vscode-icon-foreground);\r\n}\r\n\r\n/* Элемент объекта */\r\n.role-object-item {\r\n  display: flex;\r\n  align-items: center;\r\n  gap: 6px;\r\n  padding: 3px 8px 3px 22px;\r\n  font-size: 12px;\r\n  cursor: pointer;\r\n  color: var(--vscode-foreground);\r\n  border-bottom: 1px solid transparent;\r\n}\r\n\r\n.role-object-item:hover {\r\n  background-color: var(--vscode-list-hoverBackground);\r\n}\r\n\r\n.role-object-item.selected {\r\n  background-color: var(--vscode-list-activeSelectionBackground);\r\n  color: var(--vscode-list-activeSelectionForeground);\r\n}\r\n\r\n.role-object-item.has-rights {\r\n  font-weight: 600;\r\n}\r\n\r\n.role-object-item-icon {\r\n  font-size: 14px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n.role-object-item-name {\r\n  flex: 1;\r\n  overflow: hidden;\r\n  text-overflow: ellipsis;\r\n  white-space: nowrap;\r\n}\r\n\r\n.role-object-item-badge {\r\n  font-size: 10px;\r\n  padding: 1px 4px;\r\n  border-radius: 8px;\r\n  background-color: var(--vscode-badge-background);\r\n  color: var(--vscode-badge-foreground);\r\n  flex-shrink: 0;\r\n}\r\n\r\n/* Правая панель — таблица прав */\r\n.role-rights-panel {\r\n  flex: 1;\r\n  display: flex;\r\n  flex-direction: column;\r\n  overflow: hidden;\r\n  min-width: 0;\r\n}\r\n\r\n.role-rights-panel-header {\r\n  padding: 6px 10px;\r\n  font-size: 11px;\r\n  font-weight: 600;\r\n  text-transform: uppercase;\r\n  letter-spacing: 0.05em;\r\n  color: var(--vscode-sideBarTitle-foreground);\r\n  background-color: var(--vscode-sideBar-background);\r\n  border-bottom: 1px solid var(--vscode-panel-border);\r\n  flex-shrink: 0;\r\n}\r\n\r\n.role-rights-empty {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  flex: 1;\r\n  color: var(--vscode-descriptionForeground);\r\n  font-size: 13px;\r\n  font-style: italic;\r\n}\r\n\r\n/* Таблица прав */\r\n.role-rights-table-wrapper {\r\n  flex: 1;\r\n  overflow: auto;\r\n}\r\n\r\n.role-rights-table {\r\n  width: 100%;\r\n  border-colla