1px solid var(--vscode-panel-border);\r\n  background-color: var(--vscode-sideBar-background);\r\n  min-height: 28px;\r\n  flex-shrink: 0;\r\n}\r\n\r\n/* Кнопки */\r\n.btn {\r\n  padding: 5px 12px;\r\n  border: none;\r\n  border-radius: 2px;\r\n  cursor: pointer;\r\n  font-size: 12px;\r\n  font-family: var(--vscode-font-family);\r\n  transition: opacity 0.15s;\r\n}\r\n\r\n.btn:hover {\r\n  opacity: 0.85;\r\n}\r\n\r\n.btn:disabled {\r\n  opacity: 0.5;\r\n  cursor: not-allowed;\r\n}\r\n\r\n.btn-primary {\r\n  background-color: var(--vscode-button-background);\r\n  color: var(--vscode-button-foreground);\r\n}\r\n\r\n.btn-secondary {\r\n  background-color: var(--vscode-button-secondaryBackground);\r\n  color: var(--vscode-button-secondaryForeground);\r\n}\r\n\r\n/* Строка быстрых действий над таблицей прав */\r\n.role-rights-toolbar {\r\n  display: flex;\r\n  gap: 6px;\r\n  align-items: center;\r\n  padding: 5px 10px;\r\n  border-bottom: 1px solid var(--vscode-panel-border);\r\n  background-color: var(--vscode-editor-background);\r\n  flex-shrink: 0;\r\n}\r\n\r\n.role-rights-toolbar-label {\r\n  font-size: 11px;\r\n  color: var(--vscode-descriptionForeground);\r\n  margin-right: 4px;\r\n}\r\n\r\n/* Модальное окно RLS */\r\n.rls-modal-overlay {\r\n  position: fixed;\r\n  inset: 0;\r\n  background: rgba(0, 0, 0, 0.5);\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  z-index: 1000;\r\n}\r\n\r\n.rls-modal {\r\n  background: var(--vscode-editor-background);\r\n  border: 1px solid var(--vscode-panel-border);\r\n  border-radius: 4px;\r\n  padding: 16px;\r\n  min-width: 480px;\r\n  max-width: 700px;\r\n  width: 90%;\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 10px;\r\n  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.3);\r\n}\r\n\r\n.rls-modal-title {\r\n  font-size: 13px;\r\n  font-weight: 600;\r\n  color: var(--vscode-foreground);\r\n  border-bottom: 1px solid var(--vscode-panel-border);\r\n  padding-bottom: 8px;\r\n}\r\n\r\n.rls-modal label {\r\n  font-size: 12px;\r\n  color: var(--vscode-foreground);\r\n  display: block;\r\n  margin-bottom: 3px;\r\n}\r\n\r\n.rls-modal textarea {\r\n  width: 100%;\r\n  box-sizing: border-box;\r\n  min-height: 80px;\r\n  padding: 6px 8px;\r\n  background-color: var(--vscode-input-background);\r\n  color: var(--vscode-input-foreground);\r\n  border: 1px solid var(--vscode-input-border);\r\n  border-radius: 2px;\r\n  font-family: var(--vscode-editor-font-family, monospace);\r\n  font-size: 12px;\r\n  resize: vertical;\r\n  outline: none;\r\n}\r\n\r\n.rls-modal textarea:focus {\r\n  border-color: var(--vscode-focusBorder);\r\n}\r\n\r\n.rls-modal-actions {\r\n  display: flex;\r\n  gap: 8px;\r\n  justify-content: flex-end;\r\n}\r\n\r\n/* Спиннер загрузки */\r\n.role-editor-loading {\r\n  display: flex;\r\n  align-items: center;\r\n  justify-content: center;\r\n  flex: 1;\r\n  font-size: 13px;\r\n  color: var(--vscode-descriptionForeground);\r\n}\r\n"],"sourceRoot":""}]);
