/* Панель свойств */
.template-properties-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow-y: auto;
}

.template-properties-empty {
    padding: 24px;
    text-align: center;
    color: var(--vscode-descriptionForeground);
}

.template-properties-header {
    padding: 16px;
    border-bottom: 1px solid var(--vscode-panel-border);
    background-color: var(--vscode-sideBar-background);
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    position: relative;
}

.template-properties-header h3 {
    margin: 0 0 8px 0;
    font-size: var(--vscode-font-size);
    font-weight: 600;
    flex: 1;
}

.template-properties-close-button {
    background: none;
    border: none;
    color: var(--vscode-foreground);
    font-size: 24px;
    line-height: 1;
    cursor: pointer;
    padding: 0;
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0.7;
    transition: opacity 0.2s;
    margin-left: 8px;
    flex-shrink: 0;
}

.template-properties-close-button:hover {
    opacity: 1;
    background-color: var(--vscode-list-hoverBackground);
    border-radius: 2px;
}

.template-properties-range-info {
    font-size: calc(var(--vscode-font-size) - 1px);
    color: var(--vscode-descriptionForeground);
}

.template-properties-content {
    padding: 16px;
    flex: 1;
}

.template-properties-section {
    margin-bottom: 24px;
}

.template-properties-section h4 {
    margin: 0 0 8px 0;
    font-size: calc(var(--vscode-font-size) - 1px);
    font-weight: 600;
    color: var(--vscode-foreground);
}

.template-properties-position {
    display: flex;
    gap: 16px;
    padding: 8px;
    background-color: var(--vscode-input-background);
    border-radius: 4px;
    font-size: calc(var(--vscode-font-size) - 1px);
}

.template-properties-placeholder-small {
    padding: 8px;
    text-align: center;
    color: var(--vscode-descriptionForeground);
    font-size: calc(var(--vscode-font-size) - 1px);
    border: 1px dashed var(--vscode-panel-border);
    border-radius: 4px;
}

.template-properties-button {
    width: 100%;
    padding: 6px 12px;
    background-color: var(--vscode-button-background);
    color: var(--vscode-button-foreground);
    border: 1px solid var(--vscode-button-border);
    border-radius: 2px;
    cursor: pointer;
    font-size: calc(var(--vscode-font-size) - 1px);
    font-family: var(--vscode-font-family);
    margin-bottom: 8px;
}

.template-properties-button:hover {
    background-color: var(--vscode-button-hoverBackground);
}

.template-properties-named-areas,
.template-properties-all-named-areas {
    margin-top: 8px;
}

.template-properties-named-areas-label {
    font-size: calc(var(--vscode-font-size) - 1px);
    font-weight: 500;
    color: var(--vscode-foreground);
    margin-bottom: 8px;
}

.template-properties-named-area-item {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 6px 8px;
    background-color: var(--vscode-input-background);
    border-radius: 2px;
    margin-bottom: 4px;
    font-size: calc(var(--vscode-font-size) - 1px);
}

.template-properties-named-area-name {
    font-weight: 500;
    color: var(--vscode-foreground);
}

.template-properties-named-area-info {
    font-size: calc(var(--vscode-font-size) - 2px);
    color: var(--vscode-descriptionForeground);
}

.template-properties-named-area-actions {
    display: flex;
    gap: 4px;
}

.template-properties-named-area-button {
    padding: 2px 6px;
    background-color: transparent;
    color: var(--vscode-foreground);
    border: 1px solid var(--vscode-panel-border);
    border-radius: 2px;
    cursor: pointer;
    font-size: calc(var(--vscode-font-size) - 1px);
    min-width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.template-properties-named-area-button:hover {
    background-color: var(--vscode-list-hoverBackground);
}

.template-properties-input {
    width: 100%;
    padding: 6px 8px;
    background-color: var(--vscode-input-background);
    color: var(--vscode-input-foreground);
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
    font-size: var(--vscode-font-size);
    font-family: var(--vscode-font-family);
}

.template-properties-input:focus {
    outline: 1px solid var(--vscode-focusBorder);
    outline-offset: -1px;
}

.template-properties-button-small {
    padding: 4px 8px;
    background-color: var(--vscode-button-secondaryBackground);
    color: var(--vscode-button-secondaryForeground);
    border: 1px solid var(--vscode-button-border);
    border-radius: 2px;
    cursor: pointer;
    font-size: calc(var(--vscode-font-size) - 1px);
    font-family: var(--vscode-font-family);
    margin-right: 4px;
}

.template-properties-button-small:hover {
    background-color: var(--vscode-button-secondaryHoverBackground);
}

.template-properties-note-display {
    padding: 8px;
    background-color: var(--vscode-input-background);
    border-radius: 4px;
}

.template-properties-note-text {
    margin-bottom: 8px;
    font-size: calc(var(--vscode-font-size) - 1px);
    color: var(--vscode-foreground);
    white-space: pre-wrap;
}

.template-properties-note-actions {
    display: flex;
    gap: 4px;
}

.template-properties-format-info,
.template-properties-font-info {
    font-size: calc(var(--vscode-font-size) - 1px);
    color: var(--vscode-foreground);
    line-height: 1.6;
}

.template-properties-format-edit,
.template-properties-font-edit {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.template-properties-format-field {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.template-properties-format-field > label {
    font-size: calc(var(--vscode-font-size) - 1px);
    color: var(--vscode-foreground);
    font-weight: 500;
}

.template-properties-format-field select {
    width: 100%;
    padding: 6px 8px;
    background-color: var(--vscode-input-background);
    color: var(--vscode-input-foreground);
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
    font-size: var(--vscode-font-size);
    font-family: var(--vscode-font-family);
}

.template-properties-format-field select:focus {
    outline: 1px solid var(--vscode-focusBorder);
    outline-offset: -1px;
}

/* Переключатель формата заполнения */
.fill-pattern-toggle {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.fill-pattern-toggle-header {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.fill-pattern-toggle-header label {
    font-size: calc(var(--vscode-font-size) - 1px);
    font-weight: 500;
    color: var(--vscode-foreground);
}

.fill-pattern-toggle-buttons {
    display: flex;
    gap: 4px;
}

.fill-pattern-toggle-button {
    flex: 1;
    padding: 6px 12px;
    background-color: var(--vscode-button-secondaryBackground);
    color: var(--vscode-button-secondaryForeground);
    border: 1px solid var(--vscode-button-border);
    border-radius: 2px;
    cursor: pointer;
    font-size: calc(var(--vscode-font-size) - 1px);
    transition: background-color 0.2s;
}

.fill-pattern-toggle-button:hover {
    background-color: var(--vscode-button-secondaryHoverBackground);
}

.fill-pattern-toggle-button.active {
    background-color: var(--vscode-button-background);
    color: var(--vscode-button-foreground);
}

.fill-pattern-parameter-input,
.fill-pattern-template-input {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.fill-pattern-parameter-input label,
.fill-pattern-template-input label {
    font-size: calc(var(--vscode-font-size) - 1px);
    color: var(--vscode-foreground);
}

.fill-pattern-input {
    padding: 6px 8px;
    background-color: var(--vscode-input-background);
    color: var(--vscode-input-foreground);
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
    font-size: var(--vscode-font-size);
    font-family: var(--vscode-font-family);
}

.fill-pattern-input:focus {
    outline: 1px solid var(--vscode-focusBorder);
    outline-offset: -1px;
}

.fill-pattern-textarea {
    padding: 6px 8px;
    background-color: var(--vscode-input-background);
    color: var(--vscode-input-foreground);
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
    font-size: var(--vscode-font-size);
    font-family: var(--vscode-font-family);
    resize: vertical;
    min-height: 60px;
}

.fill-pattern-textarea:focus {
    outline: 1px solid var(--vscode-focusBorder);
    outline-offset: -1px;
}

.fill-pattern-preview {
    padding: 8px;
    background-color: var(--vscode-textBlockQuote-background);
    border-left: 3px solid var(--vscode-textBlockQuote-border);
    border-radius: 2px;
    font-size: calc(var(--vscode-font-size) - 1px);
    color: var(--vscode-foreground);
}

.fill-pattern-preview code {
    font-family: var(--vscode-editor-font-family);
    background-color: var(--vscode-textCodeBlock-background);
    padding: 2px 4px;
    border-radius: 2px;
}

/* Диалог именованной области */
.named-area-dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.named-area-dialog {
    background-color: var(--vscode-editor-background);
    border: 1px solid var(--vscode-panel-border);
    border-radius: 4px;
    min-width: 400px;
    max-width: 600px;
    max-height: 80vh;
    display: flex;
    flex-direction: column;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}

.named-area-dialog-header {
    padding: 16px;
    border-bottom: 1px solid var(--vscode-panel-border);
}

.named-area-dialog-header h3 {
    margin: 0;
    font-size: var(--vscode-font-size);
    font-weight: 600;
    color: var(--vscode-foreground);
}

.named-area-dialog-content {
    padding: 16px;
    overflow-y: auto;
    flex: 1;
}

.named-area-dialog-error {
    padding: 8px 12px;
    background-color: var(--vscode-inputValidation-errorBackground);
    color: var(--vscode-inputValidation-errorForeground);
    border: 1px solid var(--vscode-inputValidation-errorBorder);
    border-radius: 2px;
    margin-bottom: 16px;
    font-size: calc(var(--vscode-font-size) - 1px);
}

.named-area-dialog-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 16px;
}

.named-area-dialog-field label {
    font-size: calc(var(--vscode-font-size) - 1px);
    color: var(--vscode-foreground);
    font-weight: 500;
}

.named-area-dialog-input,
.named-area-dialog-select {
    padding: 6px 8px;
    background-color: var(--vscode-input-background);
    color: var(--vscode-input-foreground);
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
    font-size: var(--vscode-font-size);
    font-family: var(--vscode-font-family);
}

.named-area-dialog-input:focus,
.named-area-dialog-select:focus,
.named-area-dialog-textarea:focus {
    outline: 1px solid var(--vscode-focusBorder);
    outline-offset: -1px;
}

.named-area-dialog-input:disabled {
    opacity: 0.6;
    cursor: not-allowed;
    background-color: var(--vscode-input-disabledBackground);
}

.named-area-dialog-hint {
    margin-top: 4px;
    font-size: calc(var(--vscode-font-size) - 1px);
    color: var(--vscode-descriptionForeground);
    font-style: italic;
}

.named-area-dialog-textarea {
    padding: 6px 8px;
    background-color: var(--vscode-input-background);
    color: var(--vscode-input-foreground);
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
    font-size: var(--vscode-font-size);
    font-family: var(--vscode-font-family);
    resize: vertical;
    min-height: 100px;
    width: 100%;
}

.named-area-dialog-footer {
    padding: 16px;
    border-top: 1px solid var(--vscode-panel-border);
    display: flex;
    gap: 8px;
    justify-content: flex-end;
}

.named-area-dialog-button {
    padding: 6px 16px;
    background-color: var(--vscode-button-secondaryBackground);
    color: var(--vscode-button-secondaryForeground);
    border: 1px solid var(--vscode-button-border);
    border-radius: 2px;
    cursor: pointer;
    font-size: var(--vscode-font-size);
    font-family: var(--vscode-font-family);
}

.named-area-dialog-button:hover {
    background-color: var(--vscode-button-secondaryHoverBackground);
}

.named-area-dialog-button-primary {
    background-color: var(--vscode-button-background);
    color: var(--vscode-button-foreground);
}

.named-area-dialog-button-primary:hover {
    background-color: var(--vscode-button-hoverBackground);
}

/* Диалог выбора цвета */
.color-picker-dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.color-picker-dialog {
    background-color: var(--vscode-editor-background);
    border: 1px solid var(--vscode-panel-border);
    border-radius: 4px;
    min-width: 400px;
    max-width: 500px;
    display: flex;
    flex-direction: column;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}

.color-picker-dialog-header {
    padding: 16px;
    border-bottom: 1px solid var(--vscode-panel-border);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.color-picker-dialog-header h3 {
    margin: 0;
    font-size: var(--vscode-font-size);
    font-weight: 600;
    color: var(--vscode-foreground);
}

.color-picker-dialog-close {
    background: none;
    border: none;
    color: var(--vscode-foreground);
    font-size: 24px;
    line-height: 1;
    cursor: pointer;
    padding: 0;
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0.7;
    transition: opacity 0.2s;
}

.color-picker-dialog-close:hover {
    opacity: 1;
    background-color: var(--vscode-list-hoverBackground);
    border-radius: 2px;
}

.color-picker-dialog-content {
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.color-picker-mode-selector {
    display: flex;
    gap: 8px;
    border-bottom: 1px solid var(--vscode-panel-border);
    padding-bottom: 8px;
}

.color-picker-mode-button {
    flex: 1;
    padding: 8px 16px;
    background-color: var(--vscode-input-background);
    color: var(--vscode-input-foreground);
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
    cursor: pointer;
    font-size: var(--vscode-font-size);
    transition: background-color 0.2s;
}

.color-picker-mode-button:hover {
    background-color: var(--vscode-list-hoverBackground);
}

.color-picker-mode-button.active {
    background-color: var(--vscode-button-background);
    color: var(--vscode-button-foreground);
    border-color: var(--vscode-button-background);
}

.color-picker-hex-section,
.color-picker-style-section {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.color-picker-input-group {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.color-picker-input-group label {
    font-size: var(--vscode-font-size);
    color: var(--vscode-foreground);
}

.color-picker-hex-input-wrapper {
    display: flex;
    gap: 8px;
    align-items: center;
}

.color-picker-input {
    flex: 1;
    padding: 6px 8px;
    background-color: var(--vscode-input-background);
    color: var(--vscode-input-foreground);
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
    font-size: var(--vscode-font-size);
    font-family: var(--vscode-font-family);
}

.color-picker-input:focus {
    outline: 1px solid var(--vscode-focusBorder);
    outline-offset: -1px;
}

.color-picker-preview {
    width: 40px;
    height: 32px;
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
    flex-shrink: 0;
}

.color-picker-palette-section,
.color-picker-style-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.color-picker-palette-section label,
.color-picker-style-list label {
    font-size: var(--vscode-font-size);
    color: var(--vscode-foreground);
}

.color-picker-palette {
    display: grid;
    grid-template-columns: repeat(8, 1fr);
    gap: 4px;
}

.color-picker-palette-item {
    width: 32px;
    height: 32px;
    border: 2px solid var(--vscode-input-border);
    border-radius: 2px;
    cursor: pointer;
    padding: 0;
    transition: transform 0.1s, border-color 0.1s;
}

.color-picker-palette-item:hover {
    transform: scale(1.1);
    border-color: var(--vscode-focusBorder);
    z-index: 1;
    position: relative;
}

.color-picker-palette-item.selected {
    border-color: var(--vscode-focusBorder);
    border-width: 3px;
    transform: scale(1.1);
    z-index: 1;
    position: relative;
}

.color-picker-style-buttons {
    display: flex;
    flex-direction: column;
    gap: 4px;
    max-height: 280px;
    overflow-y: auto;
}

.color-picker-style-button {
    padding: 8px 12px;
    background-color: var(--vscode-input-background);
    color: var(--vscode-input-foreground);
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
    cursor: pointer;
    font-size: calc(var(--vscode-font-size) - 1px);
    text-align: left;
    transition: background-color 0.2s;
}

.color-picker-style-button:hover {
    background-color: var(--vscode-list-hoverBackground);
}

.color-picker-style-button.selected {
    background-color: var(--vscode-button-background);
    color: var(--vscode-button-foreground);
    border-color: var(--vscode-button-background);
}

.color-picker-error {
    padding: 8px 12px;
    background-color: var(--vscode-inputValidation-errorBackground);
    color: var(--vscode-inputValidation-errorForeground);
    border: 1px solid var(--vscode-inputValidation-errorBorder);
    border-radius: 2px;
    font-size: calc(var(--vscode-font-size) - 1px);
}

.color-picker-dialog-actions {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
    padding-top: 8px;
    border-top: 1px solid var(--vscode-panel-border);
}

.color-picker-button {
    padding: 6px 16px;
    border: none;
    border-radius: 2px;
    cursor: pointer;
    font-size: var(--vscode-font-size);
    transition: background-color 0.2s;
}

.color-picker-button-cancel {
    background-color: var(--vscode-button-secondaryBackground);
    color: var(--vscode-button-secondaryForeground);
}

.color-picker-button-cancel:hover {
    background-color: var(--vscode-button-secondaryHoverBackground);
}

.color-picker-button-save {
    background-color: var(--vscode-button-background);
    color: var(--vscode-button-foreground);
}

.color-picker-button-save:hover {
    background-color: var(--vscode-button-hoverBackground);
}

