    background-color: var(--vscode-input-background);
    color: var(--vscode-input-foreground);
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
    font-size: var(--vscode-font-size);
    font-family: var(--vscode-font-family);
}

.font-builder-input:focus {
    outline: 1px solid var(--vscode-focusBorder);
    outline-offset: -1px;
}

.font-builder-styles {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 8px;
    background-color: var(--vscode-input-background);
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
}

.font-builder-checkbox-label {
    display: flex;
    align-items: center;
    gap: 8px;
    cursor: pointer;
    font-size: var(--vscode-font-size);
    color: var(--vscode-foreground);
}

.font-builder-checkbox-label input[type="checkbox"] {
    width: 16px;
    height: 16px;
    cursor: pointer;
}

.font-builder-error {
    padding: 8px 12px;
    background-color: var(--vscode-inputValidation-errorBackground);
    color: var(--vscode-inputValidation-errorForeground);
    border: 1px solid var(--vscode-inputValidation-errorBorder);
    border-radius: 2px;
    font-size: calc(var(--vscode-font-size) - 1px);
}

.font-builder-dialog-actions {
    display: flex;
    justify-content: flex-end;
    gap: 8px;
    padding-top: 8px;
    border-top: 1px solid var(--vscode-panel-border);
}

.font-builder-button {
    padding: 6px 16px;
    border: none;
    border-radius: 2px;
    cursor: pointer;
    font-size: var(--vscode-font-size);
    transition: background-color 0.2s;
}

.font-builder-button-cancel {
    background-color: var(--vscode-button-secondaryBackground);
    color: var(--vscode-button-secondaryForeground);
}

.font-builder-button-cancel:hover {
    background-color: var(--vscode-button-secondaryHoverBackground);
}

.font-builder-button-save {
    background-color: var(--vscode-button-background);
    color: var(--vscode-button-foreground);
}

.font-builder-button-save:hover {
    background-color: var(--vscode-button-hoverBackground);
}

/* Диалог управления именованными областями */
.named-areas-dialog-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.named-areas-dialog {
    background-color: var(--vscode-editor-background);
    border: 1px solid var(--vscode-panel-border);
    border-radius: 4px;
    min-width: 500px;
    max-width: 700px;
    max-height: 80vh;
    display: flex;
    flex-direction: column;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
}

.named-areas-dialog-header {
    padding: 16px;
    border-bottom: 1px solid var(--vscode-panel-border);
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.named-areas-dialog-header h3 {
    margin: 0;
    font-size: var(--vscode-font-size);
    font-weight: 600;
    color: var(--vscode-foreground);
}

.named-areas-dialog-close {
    background: none;
    border: none;
    color: var(--vscode-foreground);
    font-size: 24px;
    line-height: 1;
    cursor: pointer;
    padding: 0;
    width: 24px;
    height: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0.7;
    transition: opacity 0.2s;
}

.named-areas-dialog-close:hover:not(:disabled) {
    opacity: 1;
    background-color: var(--vscode-list-hoverBackground);
    border-radius: 2px;
}

.named-areas-dialog-close:disabled {
    opacity: 0.3;
    cursor: not-allowed;
}

.named-areas-dialog-content {
    padding: 16px;
    overflow-y: auto;
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.named-areas-dialog-error {
    padding: 8px 12px;
    background-color: var(--vscode-inputValidation-errorBackground);
    color: var(--vscode-inputValidation-errorForeground);
    border: 1px solid var(--vscode-inputValidation-errorBorder);
    border-radius: 2px;
    font-size: calc(var(--vscode-font-size) - 1px);
}

.named-areas-list-header {
    display: flex;
    justify-content: flex-end;
}

.named-areas-button-primary {
    padding: 8px 16px;
    background-color: var(--vscode-button-background);
    color: var(--vscode-button-foreground);
    border: none;
    border-radius: 2px;
    cursor: pointer;
    font-size: var(--vscode-font-size);
    transition: background-color 0.2s;
}

.named-areas-button-primary:hover:not(:disabled) {
    background-color: var(--vscode-button-hoverBackground);
}

.named-areas-button-primary:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.named-areas-empty {
    padding: 24px;
    text-align: center;
    color: var(--vscode-descriptionForeground);
    font-style: italic;
}

.named-areas-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.named-areas-list-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px;
    background-color: var(--vscode-input-background);
    border: 1px solid var(--vscode-input-border);
    border-radius: 2px;
    transition: background-color 0.2s;
}

.named-areas-list-item:hover {
    background-color: var(--vscode-list-hoverBackground);
}

.named-areas-list-item-info {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.named-areas-list-item-name {
    font-size: var(--vscode-font-size);
    color: var(--vscode-foreground);
}

.named-areas-list-item-details {
    display: flex;
    gap: 16px;
    font-size: calc(var(--vscode-font-size) - 1px);
    color: var(--vscode-descriptionForeground);
}

.named-areas-list-item-actions {
    display: flex;
    gap: 4px;
}

.named-areas-action-button {
    padding: 4px 8px;
    background-color: transparent;
    border: 1px solid var(--vscode-button-border);
    border-radius: 2px;
    cursor: pointer;
    font-size: var(--vscode-font-size);
    transition: background-color 0.2s;
    min-width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.named-areas-action-button:hover:not(:disabled) {
    background-color: var(--vscode-list-hoverBackground);
}

.named-areas-action-button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

